62	
63	  putreg32(0x0, SG2000_PLIC_ENABLE1);
64	  putreg32(0x0, SG2000_PLIC_ENABLE2);
65	
66	  /* Clear pendings in PLIC */
67	
68	  claim = getreg32(SG2000_PLIC_CLAIM);
69	  putreg32(claim, SG2000_PLIC_CLAIM);
70	
71	  /* Colorize the interrupt stack for debug purposes */
72	
73	#if defined(CONFIG_STACK_COLORATION) && CONFIG_ARCH_INTERRUPTSTACK > 15
74	  size_t intstack_size = (CONFIG_ARCH_INTERRUPTSTACK & ~15);
75	  riscv_stack_color(g_intstackalloc, intstack_size);
76	#endif
77	
78	  /* Set priority for all global interrupts to 1 (lowest) */
79	
80	  int id;
81	
82	  for (id = 1; id <= NR_IRQS; id++)
83	    {
84	      putreg32(1, (uintptr_t)(SG2000_PLIC_PRIORITY + 4 * id));
85	    }
86	
87	  /* Set irq threshold to 0 (permits all global interrupts) */
88	
