49	 ****************************************************************************/
50	
51	static const char *g_reasons_str[RISCV_MAX_EXCEPTION + 1] =
52	{
53	  "Instruction address misaligned",
54	  "Instruction access fault",
55	  "Illegal instruction",
56	  "Breakpoint",
57	  "Load address misaligned",
58	  "Load access fault",
59	  "Store/AMO address misaligned",
60	  "Store/AMO access fault",
61	  "Environment call from U-mode",
62	  "Environment call from S-mode",
63	  "Environment call from H-mode",
64	  "Environment call from M-mode",
65	  "Instruction page fault",
66	  "Load page fault",
