80	/****************************************************************************
81	 * Public Functions
82	 ****************************************************************************/
83	
84	/****************************************************************************
85	 * Name: riscv_exception
86	 *
87	 * Description:
88	 *   This is the exception handler.
89	 *
90	 ****************************************************************************/
91	
92	int riscv_exception(int mcause, void *regs, void *args)
93	{
94	#ifdef CONFIG_ARCH_KERNEL_STACK
95	  struct tcb_s *tcb = this_task();
96	#endif
97	  uintreg_t cause = mcause & RISCV_IRQ_MASK;
98	
99	  _alert("EXCEPTION: %s. MCAUSE: %" PRIxREG ", EPC: %" PRIxREG
100	         ", MTVAL: %" PRIxREG "\n",
101	         mcause > RISCV_MAX_EXCEPTION ? "Unknown" : g_reasons_str[cause],
102	         cause, READ_CSR(CSR_EPC), READ_CSR(CSR_TVAL));
103	
104	#ifdef CONFIG_ARCH_KERNEL_STACK
105	  if ((atomic_read(&tcb->flags) & TCB_FLAG_TTYPE_MASK) !=
106	      TCB_FLAG_TTYPE_KERNEL)
107	    {
108	      _alert("Segmentation fault in PID %d: %s\n",
109	             tcb->pid, get_task_name(tcb));
110	
111	      atomic_or(&tcb->flags, TCB_FLAG_FORCED_CANCEL);
112	
113	      /* Return to _exit function in privileged mode with argument SIGSEGV */
114	
115	      running_regs()[REG_EPC] = _exit;
116	      running_regs()[REG_A0] = (void *)SIGSEGV;
117	      ((uintreg_t *)running_regs())[REG_INT_CTX] |= STATUS_PPP;
118	
119	      /* Continue with kernel stack in use. The frame(s) in kernel stack
120	       * are no longer needed, so just set it to top
121	       */
122	
123	      running_regs()[REG_SP] = tcb->xcp.ktopstk;
124	    }
125	  else
126	#endif
127	    {
128	      _alert("PANIC!!! Exception = %" PRIxREG "\n", cause);
129	      up_irq_save();
130	      up_set_interrupt_context(true);
131	      PANIC_WITH_REGS("panic", regs);
132	    }
133	
134	  return 0;
135	}
136	
137	/****************************************************************************
138	 * Name: riscv_fillpage
139	 *
140	 * Description:
141	 *   This function is an exception handler for page faults in a RISC-V.
142	 *   It is invoked when a page fault exception occurs, which is typically
143	 *   when a process tries to access a page that is not currently in memory.
144	 *
145	 *   The function takes as arguments the machine cause (mcause) which
146	 *   indicates the cause of the exception, a pointer to the register state
147	 *   at the time of the exception (regs), and a pointer to any additional
148	 *   arguments (args).
149	 *
150	 *   The function should handle the exception appropriately, typically by
151	 *   loading the required page into memory and updating the page table.
152	 *
153	 * Input Parameters:
154	 *   mcause - The machine cause of the exception.
155	 *   regs   - A pointer to the register state at the time of the exception.
156	 *   args   - A pointer to any additional arguments.
157	 *
158	 * Returned Value:
159	 *   Zero (OK) on success; a negated errno value on failure.
160	 *
161	 ****************************************************************************/
162	
163	#ifdef CONFIG_PAGING
164	int riscv_fillpage(int mcause, void *regs, void *args)
165	{
166	  uintptr_t cause = mcause & RISCV_IRQ_MASK;
167	  uintptr_t ptlast;
168	  uintptr_t ptprev;
169	  uintptr_t paddr;
170	  uintptr_t vaddr;
171	  uint32_t  ptlevel;
172	  uintptr_t satp;
173	  uint64_t  mmuflags;
174	
175	  _info("EXCEPTION: %s. MCAUSE: %" PRIxREG ", EPC: %" PRIxREG
176	        ", MTVAL: %" PRIxREG "\n",
177	        mcause > RISCV_MAX_EXCEPTION ? "Unknown" : g_reasons_str[cause],
178	        cause, READ_CSR(CSR_EPC), READ_CSR(CSR_TVAL));
179	  vaddr = MM_PGALIGNDOWN(READ_CSR(CSR_TVAL));
180	  if (vaddr >= CONFIG_ARCH_TEXT_VBASE && vaddr <= ARCH_TEXT_VEND)
181	    {
182	      mmuflags = MMU_UTEXT_FLAGS;
183	
184	      /* Write access to .text region needs to be set according to
185	       * https://github.com/apache/nuttx/pull/6193.
186	       */
187	
188	      mmuflags |= PTE_W;
189	    }
190	  else if (vaddr >= CONFIG_ARCH_DATA_VBASE && vaddr <= ARCH_DATA_VEND)
191	    {
192	      mmuflags = MMU_UDATA_FLAGS;
193	    }
194	  else if (vaddr >= CONFIG_ARCH_HEAP_VBASE && vaddr <= ARCH_HEAP_VEND)
195	    {
196	      mmuflags = MMU_UDATA_FLAGS;
197	    }
198	  else
199	    {
200	      _alert("PANIC!!! virtual address not mappable: %" PRIxPTR "\n", vaddr);
201	      up_irq_save();
202	      up_set_interrupt_context(true);
203	      PANIC_WITH_REGS("panic", regs);
204	    }
205	
206	  satp    = READ_CSR(CSR_SATP);
207	  ptprev  = riscv_pgvaddr(mmu_satp_to_paddr(satp));
208	  ptlevel = ARCH_SPGTS;
209	  paddr   = mmu_pte_to_paddr(mmu_ln_getentry(ptlevel, ptprev, vaddr));
210	  if (!paddr)
211	    {
212	      /* Nothing yet, allocate one page for final level page table */
213	
214	      paddr = mm_pgalloc(1);
215	      if (!paddr)
216	        {
217	          return -ENOMEM;
218	        }
219	
220	      /* Map the page table to the prior level */
221	
222	      mmu_ln_setentry(ptlevel, ptprev, paddr, vaddr, MMU_UPGT_FLAGS);
223	
224	      /* This is then used to map the final level */
225	
226	      riscv_pgwipe(paddr);
227	    }
228	
229	  ptlast = riscv_pgvaddr(paddr);
230	  paddr = mm_pgalloc(1);
231	  if (!paddr)
232	    {
233	      return -ENOMEM;
234	    }
235	
236	  /* Wipe the physical page memory */
237	
238	  riscv_pgwipe(paddr);
239	
240	  /* Then map the virtual address to the physical address */
241	
242	  mmu_ln_setentry(ptlevel + 1, ptlast, paddr, vaddr, mmuflags);
243	
244	  return 0;
245	}
246	#endif /* CONFIG_PAGING */
247	
248	/****************************************************************************
249	 * Name: riscv_exception_attach
250	 *
251	 * Description:
252	 *   Attach standard exception with suitable handler
253	 *
254	 ****************************************************************************/
255	
256	void riscv_exception_attach(void)
257	{
258	  irq_attach(RISCV_IRQ_IAMISALIGNED, riscv_exception, NULL);
259	  irq_attach(RISCV_IRQ_IAFAULT, riscv_exception, NULL);
260	  irq_attach(RISCV_IRQ_IINSTRUCTION, riscv_exception, NULL);
261	  irq_attach(RISCV_IRQ_BPOINT, riscv_exception, NULL);
262	  irq_attach(RISCV_IRQ_LAFAULT, riscv_exception, NULL);
263	  irq_attach(RISCV_IRQ_SAFAULT, riscv_exception, NULL);
264	
265	#ifdef CONFIG_RISCV_MISALIGNED_HANDLER
266	  irq_attach(RISCV_IRQ_LAMISALIGNED, riscv_misaligned, NULL);
267	  irq_attach(RISCV_IRQ_SAMISALIGNED, riscv_misaligned, NULL);
268	#else
269	  irq_attach(RISCV_IRQ_LAMISALIGNED, riscv_exception, NULL);
270	  irq_attach(RISCV_IRQ_SAMISALIGNED, riscv_exception, NULL);
271	#endif
272	
273	  /* Attach the ecall interrupt handler */
274	
275	#ifndef CONFIG_BUILD_FLAT
276	  irq_attach(RISCV_IRQ_ECALLU, riscv_swint, NULL);
277	#else
278	  irq_attach(RISCV_IRQ_ECALLU, riscv_exception, NULL);
279	#endif
280	
281	  irq_attach(RISCV_IRQ_ECALLS, riscv_exception, NULL);
282	  irq_attach(RISCV_IRQ_ECALLH, riscv_exception, NULL);
283	
284	#ifndef CONFIG_ARCH_USE_S_MODE
285	  irq_attach(RISCV_IRQ_ECALLM, riscv_swint, NULL);
286	#else
287	  irq_attach(RISCV_IRQ_ECALLM, riscv_exception, NULL);
288	#endif
289	
290	  irq_attach(RISCV_IRQ_INSTRUCTIONPF, riscv_exception, NULL);
