294	  irq_attach(RISCV_IRQ_STOREPF, riscv_fillpage, NULL);
295	#else
296	  irq_attach(RISCV_IRQ_LOADPF, riscv_exception, NULL);
297	  irq_attach(RISCV_IRQ_STOREPF, riscv_exception, NULL);
298	#endif
299	
300	  irq_attach(RISCV_IRQ_RESERVED14, riscv_exception, NULL);
301	
